    /** Scrapes a simple HTML page and extracts title, description, and links */
    public function test_scrape_basic_html_page(): void
    {
        $engine_config = CrawlConfig::from_json(json_encode(["maxDepth" => 0, "respectRobotsTxt" => false]));
        $engine = Crawlberg::createEngine($engine_config);
        $url = getenv('MOCK_SERVER_URL') . '/fixtures/scrape_basic_html_page';
        $result = Crawlberg::scrape($engine, $url);

        $this->assertEquals(200, $result->statusCode);
        $this->assertEquals("text/html", $result->contentType);
        $this->assertNotSame('', $result->html ?? '', 'expected non-empty value');
        $this->assertEquals("Example Domain", ($result->getMetadata()->title ?? null));
        $this->assertStringContainsString("illustrative examples", ($result->getMetadata()->description ?? null));
        $this->assertNotSame('', ($result->getMetadata()->canonicalUrl ?? null) ?? '', 'expected non-empty value');
        $this->assertGreaterThan(0, count($result->getLinks()));
        $this->assertTrue((bool)array_filter($result->getLinks(), fn ($e) => str_contains((string)$e->linkType, "external")));
        $this->assertEquals(0, count($result->getImages()));
        $this->assertEmpty(($result->getMetadata()->ogTitle ?? null));


    }


